values
  ('47109fbc-9a26-47ca-a88d-9387038c33d0', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Ecological thinking', 'This module establishes ecological thinking as the course''s first working framework. It supplies the language and representations needed before the path advances to physical environment.', 0),
  ('1f53343b-d054-41e3-bc53-eaa8da7117cd', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '47109fbc-9a26-47ca-a88d-9387038c33d0', 'subtopic'::public.curated_course_node_type, 'Scales', 'Scales identifies a specific object, distinction, or relationship within ecological thinking. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before hypotheses because that next topic assumes this starting point.', 0),
  ('ecd10e43-fc41-4fb3-9062-8afe973b723f', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '47109fbc-9a26-47ca-a88d-9387038c33d0', 'subtopic'::public.curated_course_node_type, 'Hypotheses', 'Hypotheses identifies a specific object, distinction, or relationship within ecological thinking. Learners need to recognize and use it before combining this module''s ideas in later work. After scales, hypotheses supplies what is needed to address natural history.', 1),
  ('ee451b2a-87d4-4622-9a68-45afba3bb50d', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '47109fbc-9a26-47ca-a88d-9387038c33d0', 'subtopic'::public.curated_course_node_type, 'Natural history', 'Natural history identifies a specific object, distinction, or relationship within ecological thinking. Learners need to recognize and use it before combining this module''s ideas in later work. After hypotheses, natural history supplies what is needed to address experimental and observational design.', 2),
  ('dd999a22-e608-4362-babd-e64d2c0a6bb8', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '47109fbc-9a26-47ca-a88d-9387038c33d0', 'subtopic'::public.curated_course_node_type, 'Experimental and observational design', 'Experimental and observational design connects ecological thinking to observable evidence and defines what a valid measurement or interpretation must support. As the final topic in this module, experimental and observational design carries the completed idea into physical environment.', 3),
  ('b3fa4630-4ed1-446e-a86b-11cfbe43c3de', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Physical environment', 'This module builds directly on ecological thinking and develops physical environment. It belongs here because its methods and distinctions are prerequisites for behavioral and physiological ecology.', 1),
  ('cd651276-f3a8-4aa6-9df5-34d79facff16', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'b3fa4630-4ed1-446e-a86b-11cfbe43c3de', 'subtopic'::public.curated_course_node_type, 'Climate', 'Climate identifies a specific object, distinction, or relationship within physical environment. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before water because that next topic assumes this starting point.', 0),
  ('57d7be2c-033b-457c-a34c-346ac5f8a65a', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'b3fa4630-4ed1-446e-a86b-11cfbe43c3de', 'subtopic'::public.curated_course_node_type, 'Water', 'Water identifies a specific object, distinction, or relationship within physical environment. Learners need to recognize and use it before combining this module''s ideas in later work. After climate, water supplies what is needed to address soils.', 1),
  ('6a979578-e994-4730-845f-eb2bf06021cb', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'b3fa4630-4ed1-446e-a86b-11cfbe43c3de', 'subtopic'::public.curated_course_node_type, 'Soils', 'Soils identifies a specific object, distinction, or relationship within physical environment. Learners need to recognize and use it before combining this module''s ideas in later work. After water, soils supplies what is needed to address disturbance.', 2),
  ('a68979c5-a0b9-40e6-a28c-d7f73460fb2e', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'b3fa4630-4ed1-446e-a86b-11cfbe43c3de', 'subtopic'::public.curated_course_node_type, 'Disturbance', 'Disturbance identifies a specific object, distinction, or relationship within physical environment. Learners need to recognize and use it before combining this module''s ideas in later work. After soils, disturbance supplies what is needed to address organismal constraints.', 3),
  ('048dfdf1-402b-448d-93ca-58860c651e27', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'b3fa4630-4ed1-446e-a86b-11cfbe43c3de', 'subtopic'::public.curated_course_node_type, 'Organismal constraints', 'Organismal constraints is a governing quantity in physical environment, linking local calculations to system-level behavior and offering a consistency check. As the final topic in this module, organismal constraints carries the completed idea into behavioral and physiological ecology.', 4),
  ('5d4dd277-6af3-43c5-b72e-122dd8afa460', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Behavioral and physiological ecology', 'This module builds directly on physical environment and develops behavioral and physiological ecology. It belongs here because its methods and distinctions are prerequisites for population structure.', 2),
  ('868d6dea-eed2-40ea-8164-256a75d5d4ec', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '5d4dd277-6af3-43c5-b72e-122dd8afa460', 'subtopic'::public.curated_course_node_type, 'Resources', 'Resources identifies a specific object, distinction, or relationship within behavioral and physiological ecology. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before tolerance because that next topic assumes this starting point.', 0),
  ('0158952f-555a-462d-9094-37fd54f0d40d', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '5d4dd277-6af3-43c5-b72e-122dd8afa460', 'subtopic'::public.curated_course_node_type, 'Tolerance', 'Tolerance identifies a specific object, distinction, or relationship within behavioral and physiological ecology. Learners need to recognize and use it before combining this module''s ideas in later work. After resources, tolerance supplies what is needed to address allocation.', 1),
  ('588a9207-08d8-4db5-b466-6f6d83a01f72', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '5d4dd277-6af3-43c5-b72e-122dd8afa460', 'subtopic'::public.curated_course_node_type, 'Allocation', 'Allocation identifies a specific object, distinction, or relationship within behavioral and physiological ecology. Learners need to recognize and use it before combining this module''s ideas in later work. After tolerance, allocation supplies what is needed to address optimality models.', 2),
  ('94a942eb-3c87-4ed0-aba9-9618c95fa760', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '5d4dd277-6af3-43c5-b72e-122dd8afa460', 'subtopic'::public.curated_course_node_type, 'Optimality models', 'Optimality models gives behavioral and physiological ecology a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, optimality models carries the completed idea into population structure.', 3),
  ('efff940d-b2a2-4b3d-a954-b15212a33033', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Population structure', 'This module builds directly on behavioral and physiological ecology and develops population structure. It belongs here because its methods and distinctions are prerequisites for population growth.', 3),
  ('64d8b44d-4d07-4c38-822a-f2db86bd2398', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'efff940d-b2a2-4b3d-a954-b15212a33033', 'subtopic'::public.curated_course_node_type, 'Life tables', 'Life tables identifies a specific object, distinction, or relationship within population structure. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before survivorship because that next topic assumes this starting point.', 0),
  ('0a1529e2-32fb-472e-91b9-d21d62a34917', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'efff940d-b2a2-4b3d-a954-b15212a33033', 'subtopic'::public.curated_course_node_type, 'Survivorship', 'Survivorship identifies a specific object, distinction, or relationship within population structure. Learners need to recognize and use it before combining this module''s ideas in later work. After life tables, survivorship supplies what is needed to address fecundity.', 1),
  ('728e5133-c233-470b-b1a4-9acb280d8be0', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'efff940d-b2a2-4b3d-a954-b15212a33033', 'subtopic'::public.curated_course_node_type, 'Fecundity', 'Fecundity identifies a specific object, distinction, or relationship within population structure. Learners need to recognize and use it before combining this module''s ideas in later work. After survivorship, fecundity supplies what is needed to address demographic rates.', 2),
  ('517eb678-8396-4383-8e31-098014fdb791', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'efff940d-b2a2-4b3d-a954-b15212a33033', 'subtopic'::public.curated_course_node_type, 'Demographic rates', 'Demographic rates identifies a specific object, distinction, or relationship within population structure. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, demographic rates carries the completed idea into population growth.', 3),
  ('ed5b34b8-6f64-4f8c-8bbc-ce020586a842', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Population growth', 'This module builds directly on population structure and develops population growth. It belongs here because its methods and distinctions are prerequisites for life histories and metapopulations.', 4),
  ('b3474ea5-be29-42a5-bb84-d8c2df2168e0', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'ed5b34b8-6f64-4f8c-8bbc-ce020586a842', 'subtopic'::public.curated_course_node_type, 'Exponential/logistic models', 'Exponential/logistic models gives population growth a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before density dependence because that next topic assumes this starting point.', 0),
  ('182a2d35-e712-4766-be9e-f5db33e872d0', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'ed5b34b8-6f64-4f8c-8bbc-ce020586a842', 'subtopic'::public.curated_course_node_type, 'Density dependence', 'Density dependence identifies a specific object, distinction, or relationship within population growth. Learners need to recognize and use it before combining this module''s ideas in later work. After exponential/logistic models, density dependence supplies what is needed to address stochasticity.', 1),
  ('c2a2bf6d-f319-417a-b9ba-71b6c2b334b2', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'ed5b34b8-6f64-4f8c-8bbc-ce020586a842', 'subtopic'::public.curated_course_node_type, 'Stochasticity', 'Stochasticity identifies a specific object, distinction, or relationship within population growth. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, stochasticity carries the completed idea into life histories and metapopulations.', 2),
  ('fa2945af-6c45-49f2-ba89-0513787def83', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Life histories and metapopulations', 'This module builds directly on population growth and develops life histories and metapopulations. It belongs here because its methods and distinctions are prerequisites for species interactions.', 5),
  ('4dce34ea-640f-493c-a1f7-f59920da8e12', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'fa2945af-6c45-49f2-ba89-0513787def83', 'subtopic'::public.curated_course_node_type, 'Tradeoffs', 'Tradeoffs identifies a specific object, distinction, or relationship within life histories and metapopulations. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before dispersal because that next topic assumes this starting point.', 0),
  ('d8c8b6b6-5432-4943-8ce4-bb65b51ebfc6', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'fa2945af-6c45-49f2-ba89-0513787def83', 'subtopic'::public.curated_course_node_type, 'Dispersal', 'Dispersal identifies a specific object, distinction, or relationship within life histories and metapopulations. Learners need to recognize and use it before combining this module''s ideas in later work. After tradeoffs, dispersal supplies what is needed to address source–sink.', 1),
  ('e1ee91d0-be75-4913-9534-c58ec37abf31', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'fa2945af-6c45-49f2-ba89-0513787def83', 'subtopic'::public.curated_course_node_type, 'Source–sink', 'Source–sink identifies a specific object, distinction, or relationship within life histories and metapopulations. Learners need to recognize and use it before combining this module''s ideas in later work. After dispersal, source–sink supplies what is needed to address extinction risk.', 2),
  ('1ddb4bbd-94a1-47c3-9ec4-fc1ac0aed129', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'fa2945af-6c45-49f2-ba89-0513787def83', 'subtopic'::public.curated_course_node_type, 'Extinction risk', 'Extinction risk makes the validity limits of life histories and metapopulations explicit, showing when an otherwise correct method or system can become unreliable. As the final topic in this module, extinction risk carries the completed idea into species interactions.', 3),
  ('9e819d41-0bfe-4d78-a8b3-2f5c9a26654b', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Species interactions', 'This module builds directly on life histories and metapopulations and develops species interactions. It belongs here because its methods and distinctions are prerequisites for community structure.', 6),
  ('a2fdcd81-d733-42b5-8d3d-8d12224ea793', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '9e819d41-0bfe-4d78-a8b3-2f5c9a26654b', 'subtopic'::public.curated_course_node_type, 'Competition', 'Competition identifies a specific object, distinction, or relationship within species interactions. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before predation because that next topic assumes this starting point.', 0),
  ('d9009ae9-6866-4e10-b361-e87ea764dc79', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '9e819d41-0bfe-4d78-a8b3-2f5c9a26654b', 'subtopic'::public.curated_course_node_type, 'Predation', 'Predation identifies a specific object, distinction, or relationship within species interactions. Learners need to recognize and use it before combining this module''s ideas in later work. After competition, predation supplies what is needed to address herbivory.', 1),
  ('21b6cb27-d85d-42f9-ad5a-ee6d2e837eea', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '9e819d41-0bfe-4d78-a8b3-2f5c9a26654b', 'subtopic'::public.curated_course_node_type, 'Herbivory', 'Herbivory identifies a specific object, distinction, or relationship within species interactions. Learners need to recognize and use it before combining this module''s ideas in later work. After predation, herbivory supplies what is needed to address parasitism.', 2),
  ('b68827ff-ff6c-4938-84a5-ee25e29674ad', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '9e819d41-0bfe-4d78-a8b3-2f5c9a26654b', 'subtopic'::public.curated_course_node_type, 'Parasitism', 'Parasitism identifies a specific object, distinction, or relationship within species interactions. Learners need to recognize and use it before combining this module''s ideas in later work. After herbivory, parasitism supplies what is needed to address mutualism.', 3),
  ('cfc7fb7d-48d2-41be-b2e8-066e5456a6d3', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '9e819d41-0bfe-4d78-a8b3-2f5c9a26654b', 'subtopic'::public.curated_course_node_type, 'Mutualism', 'Mutualism identifies a specific object, distinction, or relationship within species interactions. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, mutualism carries the completed idea into community structure.', 4),
  ('2a4ade8b-ba14-42d6-8a29-c347c752110d', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Community structure', 'This module builds directly on species interactions and develops community structure. It belongs here because its methods and distinctions are prerequisites for ecosystem ecology.', 7),
  ('840521fa-b8b8-4ff9-abad-2395fcacb5f8', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '2a4ade8b-ba14-42d6-8a29-c347c752110d', 'subtopic'::public.curated_course_node_type, 'Diversity', 'Diversity identifies a specific object, distinction, or relationship within community structure. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before niches because that next topic assumes this starting point.', 0),
  ('bf585743-a263-49bf-91e4-454d4e459acf', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '2a4ade8b-ba14-42d6-8a29-c347c752110d', 'subtopic'::public.curated_course_node_type, 'Niches', 'Niches identifies a specific object, distinction, or relationship within community structure. Learners need to recognize and use it before combining this module''s ideas in later work. After diversity, niches supplies what is needed to address succession.', 1),
  ('2bd145a5-7ab2-439c-97a1-80cf0794b728', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '2a4ade8b-ba14-42d6-8a29-c347c752110d', 'subtopic'::public.curated_course_node_type, 'Succession', 'Succession identifies a specific object, distinction, or relationship within community structure. Learners need to recognize and use it before combining this module''s ideas in later work. After niches, succession supplies what is needed to address assembly.', 2);
