  ('5d54ebcb-b4f9-4a56-92c6-6c479b0ed48c', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '00e34896-02ea-4421-8da7-812448bb5569', 'subtopic'::public.curated_course_node_type, 'Productivity', 'Productivity identifies a specific object, distinction, or relationship within ecosystem ecology. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before decomposition because that next topic assumes this starting point.', 0),
  ('6885a875-9ff0-4188-949a-8bd5ed674f8d', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '00e34896-02ea-4421-8da7-812448bb5569', 'subtopic'::public.curated_course_node_type, 'Decomposition', 'Decomposition identifies a specific object, distinction, or relationship within ecosystem ecology. Learners need to recognize and use it before combining this module''s ideas in later work. After productivity, decomposition supplies what is needed to address energy flow.', 1),
  ('0b511395-beb4-4aae-81f3-c6dc622491ca', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '00e34896-02ea-4421-8da7-812448bb5569', 'subtopic'::public.curated_course_node_type, 'Energy flow', 'Energy flow is a governing quantity in ecosystem ecology, linking local calculations to system-level behavior and offering a consistency check. After decomposition, energy flow supplies what is needed to address nutrient cycles.', 2),
