  ('9c7b4247-ae0d-4a82-ad32-5682c2db0ccb', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '607fbfba-dd25-4ac7-ae2d-5b0e706dfe26', 'subtopic'::public.curated_course_node_type, 'Spatial scale', 'Spatial scale identifies a specific object, distinction, or relationship within landscape ecology. Learners need to recognize and use it before combining this module''s ideas in later work. After connectivity, spatial scale supplies what is needed to address remote-sensing concepts.', 2),
  ('b1f3b1c6-a99c-4e23-a6c0-5512c2c5fba4', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '607fbfba-dd25-4ac7-ae2d-5b0e706dfe26', 'subtopic'::public.curated_course_node_type, 'Remote-sensing concepts', 'Remote-sensing concepts identifies a specific object, distinction, or relationship within landscape ecology. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, remote-sensing concepts carries the completed idea into global change ecology.', 3),
  ('ce491524-0540-4e05-8320-3e175266801c', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Global change ecology', 'This module builds directly on landscape ecology and develops global change ecology. It belongs here because its methods and distinctions are prerequisites for conservation and management.', 10),
  ('e89af120-a134-4fac-8b76-08e751e2bcd8', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'ce491524-0540-4e05-8320-3e175266801c', 'subtopic'::public.curated_course_node_type, 'Climate', 'Climate identifies a specific object, distinction, or relationship within global change ecology. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before land use because that next topic assumes this starting point.', 0),
  ('2b951704-3d38-42ce-97f0-83d03de614cb', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'ce491524-0540-4e05-8320-3e175266801c', 'subtopic'::public.curated_course_node_type, 'Land use', 'Land use identifies a specific object, distinction, or relationship within global change ecology. Learners need to recognize and use it before combining this module''s ideas in later work. After climate, land use supplies what is needed to address invasions.', 1),
  ('7426771b-f66b-458d-bcdf-19143e7fdcd5', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'ce491524-0540-4e05-8320-3e175266801c', 'subtopic'::public.curated_course_node_type, 'Invasions', 'Invasions identifies a specific object, distinction, or relationship within global change ecology. Learners need to recognize and use it before combining this module''s ideas in later work. After land use, invasions supplies what is needed to address biogeochemical feedbacks.', 2),
  ('2ef25dd4-a5db-441c-8280-d8980ce5759f', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', 'ce491524-0540-4e05-8320-3e175266801c', 'subtopic'::public.curated_course_node_type, 'Biogeochemical feedbacks', 'Biogeochemical feedbacks identifies a specific object, distinction, or relationship within global change ecology. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, biogeochemical feedbacks carries the completed idea into conservation and management.', 3),
  ('09b974b9-f282-4ea6-9e43-3cfb923475d1', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', null, 'topic'::public.curated_course_node_type, 'Conservation and management', 'This culminating module draws on global change ecology and develops conservation and management. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('20ac8e8a-90ef-4531-b56d-a44df1a03c42', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '09b974b9-f282-4ea6-9e43-3cfb923475d1', 'subtopic'::public.curated_course_node_type, 'Population viability', 'Population viability identifies a specific object, distinction, or relationship within conservation and management. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before restoration because that next topic assumes this starting point.', 0),
  ('6f61d448-088e-40b5-bbad-43214be84f36', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '09b974b9-f282-4ea6-9e43-3cfb923475d1', 'subtopic'::public.curated_course_node_type, 'Restoration', 'Restoration identifies a specific object, distinction, or relationship within conservation and management. Learners need to recognize and use it before combining this module''s ideas in later work. After population viability, restoration supplies what is needed to address uncertainty.', 1),
  ('35ee7759-d4db-4d09-b80b-c7f0bb160db9', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '09b974b9-f282-4ea6-9e43-3cfb923475d1', 'subtopic'::public.curated_course_node_type, 'Uncertainty', 'Uncertainty makes the validity limits of conservation and management explicit, showing when an otherwise correct method or system can become unreliable. After restoration, uncertainty supplies what is needed to address coupled human systems.', 2),
  ('ca016b47-8e43-4a5f-931c-07caeb67ab76', 'c7d864bd-acd8-47a7-a0bb-3f010bfd8d96', '09b974b9-f282-4ea6-9e43-3cfb923475d1', 'subtopic'::public.curated_course_node_type, 'Coupled human systems', 'Coupled human systems gives conservation and management a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final course topic, coupled human systems requires ideas from the complete path to be integrated and transferred.', 3);
